// === BRACKET MATCHING ===
function isValidBrackets(s) {
  const stack = [];
  const pairs = { ')': '(', ']': '[', '}': '{' };
  for (const ch of s) {
    if ('([{'.includes(ch)) {
      stack.push(ch);  // opening bracket: push
    } else {
      // closing bracket: must match top of stack
      if (!stack.length || stack[stack.length - 1] !== pairs[ch]) return false;
      stack.pop();
    }
  }
  return stack.length === 0; // unclosed brackets remain?
}

// === MONOTONIC STACK (next greater element) ===
function nextGreater(arr) {
  const result = new Array(arr.length).fill(-1);
  const stack = []; // indices, values decrease from bottom to top

  for (let i = 0; i < arr.length; i++) {
    // pop elements for which current element is the answer (next greater)
    while (stack.length && arr[stack[stack.length - 1]] < arr[i]) {
      result[stack.pop()] = arr[i];
    }
    stack.push(i);
  }
  // remaining elements in stack have no next greater: already -1
  return result;
}
